 function selectTile(t){if(!getFree(t))return;ensureAudio();if(selected===t.id){selected=null;render();return}if(!selected){selected=t.id;render();playTone(480,.08);return}const first=tiles.find(a=>a.id===selected);if(first&&first.face===t.face){undoStack.push([first.id,t.id]);first.removed=t.removed=true;selected=null;moves++;playMatch();render();updateStats();if(tiles.every(a=>a.removed)){clearInterval(timer);setTimeout(()=>showWin(),450)}}else{selected=t.id;render();playTone(230,.11);notify('Not quite a pair. Let your eyes wander.')}}
